# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_fung_a import L,F,A,P,U,H
WB=[
E('functionary','英 /ˈfʌŋkʃənəri/；美 /ˈfʌŋkʃəneri/','工作人员；官员；执行事务的人','组织里有一个职位，也有一套要履行的职责；占着这个岗位办事的人。','来自或仿造法语 fonctionnaire，接 fonction“职能”；现代外形可联系 function 与 -ary。',L+[['拉丁 functio → 法语 fonction／fonctionnaire','职能、履职 → 担任职务的人'],['英语 functionary','执行机构事务的人员、官员']],'a government functionary 是政府工作人员；有时这个词带一点“照章办事、权限有限”的距离感。它不必是大人物，也不能一看到就翻成贪官；态度要看修饰语和语境。','a government functionary；a minor functionary；a party functionary。','official 是较普通的官员或正式工作人员名称；functionary 更突出在机构里执行某种职能，常显得较冷淡或带批评意味。',('A local functionary checked the names on the list.','一位当地工作人员核对了名单上的姓名。'),('The novel portrays a minor functionary caught between conflicting orders.','小说描写了一个夹在相互冲突的命令之间的小职员。'),sources=['https://www.etymonline.com/word/functionary','https://en.wiktionary.org/wiki/functionary']),
E('defunct','/dɪˈfʌŋkt/','已停用的；不再存在或运作的；已倒闭的','它曾经在发挥作用，如今那一段使命已经结束了。','拉丁 de-“完全、离开” + fungi“履行”形成 defungi，分词 defunctus 有已完成、死亡义，经法语或直接借入英语。',L+[['拉丁 defungi → defunctus','把职责做完 → 已结束的、死去的'],['法语 defunct 或直接借入 → 英语 defunct','不再运作、存在或使用的']],'a defunct company 是已停止经营的公司；a defunct system 是已经退出使用的系统。现在常用来谈机构、制度、设备，不是通常用来安慰人或表达某人去世的日常说法。','a defunct company；a defunct railway；now defunct。','malfunctioning 是出故障，可能修好；defunct 更强调已经结束运作或退出使用。',('The building once belonged to a defunct publishing company.','这栋楼曾属于一家已经停止经营的出版公司。'),('The museum preserves maps of a defunct railway network.','博物馆保存着一个已停用铁路网络的地图。'),sources=['https://www.etymonline.com/word/defunct','https://en.wiktionary.org/wiki/defunct']),
E('perfunctory','英 /pəˈfʌŋktəri/；美 /pərˈfʌŋktəri/','敷衍的；草草了事的；例行公事般的','心里只想着“把这一步赶紧走完”，动作做了，关心和认真没有跟上。','拉丁 per-“贯穿、做完” + fungi“履行”形成 perfungi；晚期拉丁 perfunctorius 已有草率义，再借入英语。',P,'a perfunctory apology 是像完成任务一样说句对不起；a perfunctory check 是草草检查一下。重点不是动作短，而是缺少应有的投入、注意或真心；一个简短但认真负责的检查未必 perfunctory。','a perfunctory nod；a perfunctory apology；a perfunctory inspection。','routine 只是例行、常规，可以做得很认真；perfunctory 通常带敷衍、仅走形式的批评。',('He gave the report a perfunctory glance and signed it.','他敷衍地扫了一眼报告，就签了字。'),('Her apology sounded perfunctory and did little to repair the relationship.','她的道歉听起来像走过场，没怎么改善关系。'),sources=['https://www.etymonline.com/word/perfunctory','https://en.wiktionary.org/wiki/perfunctory']),
E('perfunctorily','英 /pəˈfʌŋktərəli/；美 /pərˈfʌŋktərəli/','敷衍地；仅仅走个形式地','事情是做了，但做的人像只想在清单上打个勾。','perfunctory 的 y 变 i，再加 -ly；由形容态度变为说明动作怎么做。',H(P,'英语 perfunctory → perfunctorily','敷衍的 → 敷衍地'),'answered perfunctorily 是随口应付；checked perfunctorily 是没有认真投入的检查。这个副词对行为带有评价，不只是中性地说做得快。','reply perfunctorily；check perfunctorily；nod perfunctorily。','quickly 只说速度；perfunctorily 还说投入不足。快速完成也可以十分认真。',('The receptionist nodded perfunctorily without looking up.','接待员头也没抬，只敷衍地点了点头。'),('He checked the figures perfunctorily and missed an obvious error.','他草草核对了数字，漏掉了一个明显错误。'),sources=['https://dictionary.cambridge.org/us/dictionary/english/perfunctorily','https://en.wiktionary.org/wiki/perfunctorily']),
E('perfunctoriness','英 /pəˈfʌŋktərinəs/；美 /pərˈfʌŋktərinəs/','敷衍；草率应付的态度〔较少见〕','不是指出某一个动作，而是概括“整件事做得只剩形式”的那种感觉。','perfunctory 的 y 变 i + -ness，形成性质名词。',H(P,'英语 perfunctory → perfunctoriness','敷衍的 → 敷衍这一性质'),'the perfunctoriness of a response 说回复的态度让人觉得在应付。这个词偏书面，日常可以直接说 the reply felt careless 或用 perfunctory 修饰 reply，表达通常更轻便。','the perfunctoriness of；a sense of perfunctoriness。','perfunctoriness 强调形式走过了但缺少投入；carelessness 泛指粗心，未必涉及为了交差而走形式。',('The perfunctoriness of the reply disappointed the applicants.','回复中那种敷衍的态度令申请者失望。'),('She noticed a new perfunctoriness in the weekly checks.','她发现每周检查最近开始有些敷衍了。'),sources=['https://en.wiktionary.org/wiki/perfunctoriness']),
E('fungible','/ˈfʌndʒɪbəl/','可互换的；同等单位可以替代的','给你同等的一份就行，不需要一定是原来那一份。','中世纪拉丁 fungibilis 接拉丁 fungi“履行”，尤其是 fungi vice“代行位置或作用”；先有代替作用，再有同等物可互换。',U,'普通流通的一枚硬币，只要币种和面值相同，通常可以用另一枚替代；带纪念意义的那一枚，对收藏者就未必一样。fungible 关注是否可以不区分个体地互换，取决于比较的用途、规格和价值。','fungible goods；fungible units；treat as fungible。','replaceable 只表示能替换；fungible 更强调同等单位可以互换，不必关注是哪一个具体个体。',('For ordinary payment, coins of the same currency and denomination are generally fungible.','用于普通支付时，同币种、同面值的硬币一般可以互换。'),('The collector did not regard the two signed copies as fungible.','收藏者并不把那两本签名本视为可以随意互换的东西。'),sources=['https://www.etymonline.com/word/fungible','https://en.wiktionary.org/wiki/fungible']),
E('fungibility','/ˌfʌndʒəˈbɪləti/','可互换性；同等物可以替代的性质','重点从“这一份能换吗”，转到“这一类东西在多大程度上可互换”。','fungible 的 -ible 换为 -ibility，形成性质名词。',H(U,'英语 fungible → fungibility','可互换的 → 可互换性'),'the fungibility of a commodity 讨论同种商品的单位能否互相替代。规格、品质、用途改变，都可能影响这种判断。把它理解成“辨不辨认具体是哪一份”，比只背“可替代性”更清楚。','the fungibility of；degree of fungibility；assume fungibility。','fungibility 不等于 similarity：外观相似的两件东西，可能因身份、历史或用途不同而不能当作等价单位交换。',('The exercise illustrates fungibility using identical new tokens.','练习用完全相同的新代币来说明可互换性。'),('Differences in quality can limit the fungibility of the goods.','质量差异会限制这些货物的可互换性。'),sources=['https://en.wiktionary.org/wiki/fungibility','https://www.etymonline.com/word/fungible']),
E('nonfungible','英 /ˌnɒnˈfʌndʒɪbəl/；美 /ˌnɑːnˈfʌndʒɪbəl/','不可按同等单位互换的；非同质化的','你要的是这一件具体的东西，换成另一件同类物品并不能算完全一样。','non-“不” + fungible“可互换的”。',H(U,'英语 non- + fungible → nonfungible','可互换的 → 需要区分个体、不能等价互换的'),'一件具有独特来历的原作可以用来理解 nonfungible：另一幅同尺寸画作不能自然顶替它。这个词早于数字代币用法；“不可互换”本身也不自动说明东西稀有、昂贵或值得购买。','a nonfungible object；nonfungible assets；treat as nonfungible。','unique 强调独一无二；nonfungible 强调不能当作等价单位互换。判断重点在交换关系，而不只是外观是否不同。',('The curator treats each original manuscript as a nonfungible object.','馆长把每份原稿都视为不能用另一份同类物件等价替代的对象。'),('The rings were nonfungible to their owners because each carried a personal history.','对各自的主人而言，这些戒指不能互换，因为每一枚都承载着个人经历。'),sources=['https://en.wiktionary.org/wiki/nonfungible']),
E('functionalism','/ˈfʌŋkʃənəlɪzəm/','功能主义；重视作用与功能关系的观点','理解一个东西时先问：它在整套系统里做什么，这种作用怎样影响设计或解释？','functional + -ism“学说、主张”。',H(A,'英语 functional + -ism → functionalism','功能的 → 以功能为中心的观点'),'建筑中的 functionalism 主张形式要配合用途、材料和结构。心灵哲学中的同名观点，则按某种心理状态在系统中发挥的作用来理解它。不同领域有不同版本，不能把所有“功能主义”缩成一句“只要好用就行”。','architectural functionalism；a version of functionalism；the debate over functionalism。','functional 是功能方面的形容词；functionalism 是一种理论立场。说某物好用，不一定就在主张功能主义。',('The architect’s design reflects an interest in functionalism.','建筑师的设计体现了对功能主义的重视。'),('The seminar compared functionalism with other theories of mind.','研讨课比较了功能主义与其他心灵理论。'),sources=['https://www.etymonline.com/word/functionalism','https://www.merriam-webster.com/dictionary/functionalism','https://plato.stanford.edu/entries/functionalism/']),
E('functionalist','/ˈfʌŋkʃənəlɪst/','功能主义者；功能主义的','习惯用“它承担什么作用”作为解释或设计出发点的人，以及这种观点。','functional + -ist；与 functionalism 的主张相对应，既可作名词也可作形容词。',H(A,'英语 functional + -ist → functionalist','重视功能的观点 → 功能主义者、功能主义的'),'a functionalist 可以是某领域的功能主义者；a functionalist approach 是采取相应思路的方法。必须先看语境是在建筑、社会研究还是哲学，才知道具体主张。','a functionalist approach；functionalist architecture；a functionalist account。','functionalist 指理论立场或其支持者；functionary 指机构里的工作人员，两者虽然同族，意思相差很大。',('The functionalist asked how the parts contributed to the whole.','这位功能主义者询问，各部分怎样为整体发挥作用。'),('The article presents a functionalist account of the institution.','文章从功能主义角度解释了这个制度。'),sources=['https://www.merriam-webster.com/dictionary/functionalism','https://en.wiktionary.org/wiki/functionalist']),
E('functionalistic','/ˌfʌŋkʃənəˈlɪstɪk/','功能主义的〔较少见〕','看问题时，明显把功能和作用放在解释中心。','functional + -istic；对应 functionalism 的形容词形式。',H(A,'英语 functional + -istic → functionalistic','功能的 → 具有功能主义特点的'),'functionalistic interpretation 是按功能主义方式作出的解释。它与形容词 functionalist 大体重叠，往往出现在较正式的学术文字里，不需要理解成程度更高的一种功能。','a functionalistic view；a functionalistic interpretation。','functional 只说与功能有关；functionalistic 通常表明与某种功能主义观点有关，带有理论立场色彩。',('The reviewer questioned the book’s functionalistic interpretation.','评论者质疑了这本书的功能主义解释。'),('The essay takes a functionalistic view of social roles.','这篇文章从功能主义角度看待社会角色。'),sources=['https://en.wiktionary.org/wiki/functionalistic','https://www.merriam-webster.com/dictionary/functionalism']),
E('functionalize','/ˈfʌŋkʃənəlaɪz/','使具有功能；对……作官能化处理〔化学等〕','给原来那套结构增加能参与特定作用的部分，让它能以新的方式工作。','functional + -ize“使成为、使具有”。',H(A,'英语 functional + -ize → functionalize','有功能的 → 赋予功能、引入官能团'),'化学中常说给分子或材料表面引入官能团，使其具备特定反应性或相互作用。可以想成给结构装上新的“接口”，但这只是理解比喻，具体变化是化学结构的变化，不是随便贴上一个标签。','functionalize a surface；functionalize a molecule；functionalize with a group。','modify 泛指修改；functionalize 更突出赋予特定功能，化学用法尤其关注官能团。',('The researchers functionalized the surface to change how it interacted with water.','研究者对表面进行了官能化处理，以改变它与水的相互作用。'),('The next experiment will functionalize the molecule at a different position.','下一项实验将在分子的另一位置进行官能化。'),sources=['https://en.wiktionary.org/wiki/functionalize','https://pubs.acs.org/doi/10.1021/acscentsci.6b00032']),
E('functionalization','构词参考 /ˌfʌŋkʃənəlaɪˈzeɪʃən/','功能化；官能化〔化学等〕','把“给结构增加特定作用”的改变过程，作为一个整体来谈。','functional + -ization；与动词 functionalize 对应。',H(A,'英语 functional → functionalize／functionalization','有功能的 → 使具有功能／这一过程'),'surface functionalization 是表面功能化或官能化；在化学语境中，常涉及引入官能团来改变反应性、结合能力等性质。看这个词时，继续追问“增加了什么基团、改变了什么作用”，就不会停留在空泛的“功能化”。','surface functionalization；selective functionalization；functionalization of a molecule。','functionalization 是引入或改变功能的过程；functionality 常说现有的功能或功能性，在化学里还可有更专门的含义。',('Surface functionalization changed the material’s interaction with the coating.','表面功能化改变了材料与涂层的相互作用。'),('The paper compares two methods of molecular functionalization.','论文比较了两种分子官能化方法。'),sources=['https://en.wiktionary.org/wiki/functionalization','https://pubs.acs.org/doi/10.1021/acscentsci.6b00032']),
]
